{"code": """"Coalesce a room's raw booking rows into disjoint, non-touching busy blocks.

See SCHED-207: bookings are half-open intervals [start, end) in minutes.
Zero-length rows are cancellations and are dropped before merging; touching
intervals (b1 == a2) describe one continuous busy stretch and are merged.
"""

from __future__ import annotations


def merge_bookings(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge raw booking intervals into sorted, disjoint, non-touching busy blocks.

    Each entry is a half-open interval [start, end) in whole minutes. Entries
    with start == end are cancellations and are silently dropped. Entries with
    start > end, or that are not a two-element tuple/list of ints, raise
    ValueError. The input (and its entries) is never mutated; a new list of
    plain (int, int) tuples is returned, sorted ascending by start, with no
    two consecutive blocks overlapping or touching.
    """
    cleaned: list[tuple[int, int]] = []

    for entry in intervals:
        if not isinstance(entry, (tuple, list)) or len(entry) != 2:
            raise ValueError(
                f"booking entry must be a two-element tuple or list, got {entry!r}"
            )

        start, end = entry[0], entry[1]

        for value in (start, end):
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError(
                    f"booking bounds must be int values, got {entry!r}"
                )

        if start > end:
            raise ValueError(
                f"booking start must not exceed end, got ({start}, {end})"
            )

        if start == end:
            # Collapsed row left behind by a cancellation: contains no
            # minutes, must not appear in the output or bridge two blocks.
            continue

        cleaned.append((start, end))

    cleaned.sort(key=lambda iv: (iv[0], iv[1]))

    merged: list[tuple[int, int]] = []
    for start, end in cleaned:
        if merged and start <= merged[-1][1]:
            prev_start, prev_end = merged[-1]
            if end > prev_end:
                merged[-1] = (prev_start, end)
        else:
            merged.append((start, end))

    return merged
